function largestPairedValue(nums: number[]): number {
  const a = [...nums].sort((x, y) => x - y);
  let lo = 0, hi = a.length - 1;
  while (lo < hi && a[lo] < 0 && a[hi] > 0) {
    if (-a[lo] === a[hi]) return a[hi];
    if (-a[lo] > a[hi]) lo++;
    else hi--;
  }
  return -1;
}

